// ✅ Testable: pure rule, injected edges.
public interface IClock { DateTimeOffset UtcNow { get; } }

public sealed class FridayDiscount(IClock clock) {
    public decimal Apply(decimal total, DateTimeOffset? when = null) {
        var at = when ?? clock.UtcNow;
        return at.DayOfWeek == DayOfWeek.Friday ? total * 0.9m : total;
    }
}

// Test: no DB, no network, no sleeping until Friday.
[Fact]
public void Friday_reduces_total_by_10_percent() {
    var d = new FridayDiscount(new FixedClock(new DateTimeOffset(2026, 10, 16, 12, 0, 0, TimeSpan.Zero)));
    Assert.Equal(90m, d.Apply(100m));
}
